// src/components/HeroSection.jsx
import './HeroSection.css';

export default function HeroSection() {
  return (
    <section className="hero">
      <div className="hero-text">
        <h1>Sign up for a listening session</h1>
        <p>
          Lorem ipsum dolor sit amet, consectetur adipiscing elit. Morbi
          tincidunt elit ex, eu luctus neque feugiat sed.
        </p>
        <a href="https://your-google-form-link.com" className="signup-button">
          Sign Up
        </a>
      </div>
      <div className="hero-image">
        {/* Optional: Add <img src="/path-to-image" alt="Listening session" /> */}
      </div>
    </section>
  );
}
